import json


class ParseFailure(Exception):
    def __init__(self, message, errors):
        super().__init__(message)
        self.errors = errors


def _end_of_value(text, start):
    """Index just past the bracket-balanced value starting at text[start], string-aware."""
    depth, in_str, esc = 0, False, False
    for i in range(start, len(text)):
        ch = text[i]
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
        elif ch == '"':
            in_str = True
        elif ch in "{[":
            depth += 1
        elif ch in "}]":
            depth -= 1
            if depth == 0:
                return i + 1
    return None


def _strip_trailing_commas(s):
    out, in_str, esc = [], False, False
    for i, ch in enumerate(s):
        if in_str:
            out.append(ch)
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch == ",":
            j = i + 1
            while j < len(s) and s[j].isspace():
                j += 1
            if j < len(s) and s[j] in "}]":
                continue  # drop trailing comma
        out.append(ch)
    return "".join(out)


def extract_json_values(text):
    """Return every top-level JSON object/array found in free text, in order.
    Handles prose around it, code fences, braces inside strings and trailing commas.
    Truncated values are NOT completed (they are skipped)."""
    values, pos = [], 0
    while pos < len(text):
        starts = [p for p in (text.find("{", pos), text.find("[", pos)) if p != -1]
        if not starts:
            break
        s = min(starts)
        e = _end_of_value(text, s)
        if e is None:
            pos = s + 1
            continue
        chunk = text[s:e]
        for candidate in (chunk, _strip_trailing_commas(chunk)):
            try:
                values.append(json.loads(candidate))
                pos = e
                break
            except ValueError:
                continue
        else:
            pos = s + 1
    return values


def _type_ok(v, t):
    if t == "object":
        return isinstance(v, dict)
    if t == "array":
        return isinstance(v, list)
    if t == "string":
        return isinstance(v, str)
    if t == "boolean":
        return isinstance(v, bool)
    if t == "null":
        return v is None
    if t == "integer":
        return isinstance(v, int) and not isinstance(v, bool)
    if t == "number":
        return isinstance(v, (int, float)) and not isinstance(v, bool)
    raise ValueError("unsupported type in schema: %r" % (t,))


def validate(value, schema, path="$"):
    """Return a list of human-readable violations (empty list = valid).
    Supported keywords: type, enum, required, properties, additionalProperties (False),
    minimum, maximum, minLength, maxLength, items, minItems, maxItems."""
    errs = []
    t = schema.get("type")
    if t is not None and not _type_ok(value, t):
        return ["%s: expected %s, got %s" % (path, t, type(value).__name__)]
    if "enum" in schema and value not in schema["enum"]:
        errs.append("%s: %r not in %r" % (path, value, schema["enum"]))
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in schema and value < schema["minimum"]:
            errs.append("%s: %r < minimum %r" % (path, value, schema["minimum"]))
        if "maximum" in schema and value > schema["maximum"]:
            errs.append("%s: %r > maximum %r" % (path, value, schema["maximum"]))
    if isinstance(value, str):
        if "minLength" in schema and len(value) < schema["minLength"]:
            errs.append("%s: shorter than %d" % (path, schema["minLength"]))
        if "maxLength" in schema and len(value) > schema["maxLength"]:
            errs.append("%s: longer than %d" % (path, schema["maxLength"]))
    if isinstance(value, dict):
        props = schema.get("properties", {})
        for k in schema.get("required", []):
            if k not in value:
                errs.append("%s: missing required key %r" % (path, k))
        for k, v in value.items():
            if k in props:
                errs.extend(validate(v, props[k], "%s.%s" % (path, k)))
            elif schema.get("additionalProperties") is False:
                errs.append("%s: unexpected key %r" % (path, k))
    if isinstance(value, list):
        if "minItems" in schema and len(value) < schema["minItems"]:
            errs.append("%s: fewer than %d items" % (path, schema["minItems"]))
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            errs.append("%s: more than %d items" % (path, schema["maxItems"]))
        if "items" in schema:
            for i, v in enumerate(value):
                errs.extend(validate(v, schema["items"], "%s[%d]" % (path, i)))
    return errs


def parse_with_retries(call_model, prompt, schema, max_attempts=3):
    """call_model(prompt) -> str. Returns (value, attempts_used).
    On failure the violations are appended to the next prompt. Raises ParseFailure
    after max_attempts; nothing invalid is ever returned."""
    if not isinstance(max_attempts, int) or max_attempts < 1:
        raise ValueError("max_attempts must be an integer >= 1")
    current, last_errors = prompt, []
    for attempt in range(1, max_attempts + 1):
        raw = call_model(current)
        values = extract_json_values(raw)
        if not values:
            last_errors = ["no JSON object or array found in the reply"]
        else:
            per_candidate = [validate(v, schema) for v in values]
            for v, errs in zip(values, per_candidate):
                if not errs:
                    return v, attempt
            last_errors = per_candidate[0]
        current = (prompt + "\n\nYour previous reply was rejected:\n- "
                   + "\n- ".join(last_errors)
                   + "\nReturn only corrected JSON.")
    raise ParseFailure("gave up after %d attempts" % max_attempts, last_errors)
